{
  "root_cause": "The 'No symptoms' checkbox uses data-checkbox-exclusive=\"\" (empty string) instead of a boolean attribute, so the NHSUK checkboxes module doesn't recognize it as an exclusive option and fails to clear other symptom checkboxes when selected.",
  "repair_strategy": "Change data-checkbox-exclusive=\"\" to data-checkbox-exclusive (boolean attribute) to match the pattern used by the working 'Do not contact me' checkbox, enabling the mutual-exclusion behavior.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "6828d82d86a82e3e4e9364d8442eedcafd0b8f0740235e0d231082ffcd75878e",
      "before": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-none\" name=\"symptoms[none]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive=\"\" data-checkbox-exclusive-group=\"symptoms\">",
      "after": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-none\" name=\"symptoms[none]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive data-checkbox-exclusive-group=\"symptoms\">"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can select 'No, I do not have any of these symptoms' and have any previously selected symptom checkboxes automatically cleared, meeting exclusive choice behavior and preserving form data integrity.",
  "functional_risks": [
    "If any custom script depends on the attribute having an empty string value, it may need updating.",
    "Ensure the change does not affect visual styling or form validation."
  ],
  "verification_requirements": [
    "Verify that selecting the exclusive option via mouse or keyboard clears any previously selected symptom checkboxes.",
    "Verify that selecting a symptom after the exclusive option clears the exclusive option.",
    "Confirm that form submission reflects the correct values for symptoms[none] and symptom checkboxes.",
    "Ensure the contact checkboxes exclusive behavior remains unchanged."
  ]
}
